-- ---------------------------------------------------------------------------
-- Phase 6 — Home page content (PROJECT_PLAN.md)
--
-- The hero slides (Manage > Sliders > Home Page), the featured services
-- (shown on the home page and in the footer), the home page sections
-- (Web Pages > Home > Sections, replacing the Alam sections) and the home
-- page meta, taken from the /ci3/ home page. Run after the other
-- phase-6 content files.
--
-- The image file names are uploads (not in the repository); on another
-- environment, upload the images through the admin instead.
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;

-- Hero slides (slider group 6, the home page slider) ---------------------------

DELETE FROM `slider` WHERE `slider_id` = 6;


-- Featured services (home page and footer) ---------------------------------------

UPDATE `services` SET `service_featured` = IF(`service_slug` IN ('manicure', 'nail-art', 'nail-extensions', 'nail-care'), 1, 0);

-- Home page sections (Web Pages 1) ------------------------------------------------

DELETE FROM `web_page_sections` WHERE `page_id` = 1 AND `section_key` NOT IN ('hero', 'services_intro', 'other_services', 'nail_styles', 'gallery', 'about', 'artists', 'why', 'booking', 'offers', 'testimonials', 'location', 'instagram', 'final_cta');


-- Home page meta -------------------------------------------------------------------

UPDATE `pages` SET
    `page_title` = 'Blossom Ewa Mazur — Manicure & Nail Art Studio in Gorlice',
    `meta_description` = 'Manicure, gel nails, nail art and nail care in Gorlice, Poland — plus hair, skin, makeup and waxing. 2 Piekarska Street, above the 5.10.15 store. Book by phone or online.'
WHERE `page_id` = 1;
